import React, { useRef, useState } from 'react';
import { Button, message, Space, Tag, Popconfirm } from 'antd';
import { PlusOutlined } from '@ant-design/icons';
import BaseTable from '@/components/table/BaseTable';
import BaseModal from '@/components/common/BaseModal';
import BaseForm from '@/components/form/BaseForm';
import ActionGroup from '@/components/common/ActionGroup';
import StatusTag from '@/components/common/StatusTag';
import Permission from '@/components/permission/Permission';
import { attendanceApi } from '@/api/attendance';
import type { AttendanceShiftPayload } from '@/api/attendance';

const AttendanceShifts: React.FC = () => {
  const tableRef = useRef<any>();
  const [modalVisible, setModalVisible] = useState(false);
  const [currentRow, setCurrentRow] = useState<any>(null);
  const [form] = BaseForm.useForm();

  const columns = [
    {
      title: '班次名称',
      dataIndex: 'name',
      key: 'name',
      className: 'font-bold text-slate-900',
    },
    {
      title: '上班时间',
      dataIndex: 'on_duty_time',
      key: 'on_duty_time',
      className: 'text-slate-600',
    },
    {
      title: '下班时间',
      dataIndex: 'off_duty_time',
      key: 'off_duty_time',
      className: 'text-slate-600',
    },
    {
      title: '迟到阈值(分)',
      dataIndex: 'late_threshold',
      key: 'late_threshold',
      render: (val: number) => <span className="text-slate-600">{val} 分钟</span>,
    },
    {
      title: '早退阈值(分)',
      dataIndex: 'early_threshold',
      key: 'early_threshold',
      render: (val: number) => <span className="text-slate-600">{val} 分钟</span>,
    },
    {
      title: '状态',
      dataIndex: 'status',
      key: 'status',
      render: (status: number) => <StatusTag status={status === 1 ? 'enabled' : 'disabled'} text={status === 1 ? '启用' : '禁用'} />,
    },
    {
      title: '操作',
      key: 'action',
      fixed: 'right',
      width: 150,
      render: (_: any, record: any) => (
        <ActionGroup
          actions={[
            {
              key: 'edit',
              label: '编辑',
              permission: 'attendance:shifts:update',
              onClick: () => handleEdit(record),
            },
            {
              key: 'delete',
              label: '删除',
              permission: 'attendance:shifts:delete',
              danger: true,
              confirm: {
                title: '确认删除该班次吗？',
                onConfirm: () => handleDelete(record.id),
              },
            },
          ]}
        />
      ),
    },
  ];

  const handleAdd = () => {
    setCurrentRow(null);
    form.resetFields();
    setModalVisible(true);
  };

  const handleEdit = (record: any) => {
    setCurrentRow(record);
    form.setFieldsValue(record);
    setModalVisible(true);
  };

  const handleDelete = async (id: string) => {
