              defaultValue: 0,
              props: { min: 0, className: 'w-full' },
            },
            {
              name: 'absenteeism_threshold',
              label: '旷工阈值 (分钟)',
              type: 'number',
              defaultValue: 0,
              props: { min: 0, className: 'w-full' },
            },
            {
              name: 'status',
              label: '状态',
              type: 'select',
              options: [
                { label: '启用', value: 1 },
                { label: '禁用', value: 0 },
              ],
              defaultValue: 1,
            },
          ]}
        />
      </BaseModal>
    </div>
  );
};

export default AttendanceShifts;

