import { useMemo, useState, useEffect } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { 
  Layout, 
  Input, 
  Tree, 
  Typography, 
  Tag, 
  Space, 
  Avatar, 
  Button, 
  Empty, 
  Drawer,
  message,
  Divider,
  List,
  Card,
  Skeleton,
  Spin
} from 'antd';
import { 
  SearchOutlined, 
  PlusOutlined, 
  FolderOutlined, 
  FileTextOutlined,
  ThunderboltOutlined,
  PaperClipOutlined,
  UserOutlined,
  CloseCircleOutlined,
  LoadingOutlined
} from '@ant-design/icons';
